-- M-Core Onboarding Checklist - part 05b: seed checklist master v1 (sections E,F,G,H,I) from the M-Core onboarding PDF.
-- Run after part 4. Idempotent: inserts only what is missing in version 1. A,B,C,E = UTAMA; B,C,E submissions are urgent.
DO $seed$
DECLARE vid uuid; secs jsonb := '[["E","HR & Gaji \u2014 Data Induk Pekerja","HR & Payroll \u2014 Employee Master Data",1],["F","Jualan, CRM & Data Pelanggan","Sales, CRM & Customer Data",0],["G","Inventori, Produk & Pembekal","Inventory, Products & Suppliers",0],["H","Akses Sistem & Peranan Pengguna","System Access & User Roles",0],["I","Jenama & Templat Dokumen","Branding & Document Templates",0]]';
 items jsonb := '[["E1","Senarai Penuh Pekerja (Nama, No. IC, Jawatan, Jabatan)","Full Employee List (Name, IC No., Position, Department)","Excel/CSV","Excel/CSV","r","list",[],null,"name,ic_no,position,department,join_date,employment_type",0,"hr",{}],["E2","Tarikh Mula Bekerja & Jenis Pekerjaan","Employment Start Date & Employment Type","Sepenuh masa/separuh masa/kontrak","Full-time/part-time/contract","r","list",[],null,"name,ic_no,join_date,employment_type",0,"hr",{}],["E3","Gaji Pokok & Struktur Elaun/Potongan","Basic Salary & Allowances/Deductions Structure","Setiap pekerja","Per employee","r","list",[],null,"name,ic_no,basic_salary,allowance_name,allowance_amount,deduction_name,deduction_amount",0,"hr",{}],["E4","No. Individu KWSP/PERKESO/PCB","EPF/SOCSO/EIS/PCB Individual Numbers","Setiap pekerja","Per employee","r","list",[],null,"name,ic_no,epf_no,socso_no,tax_no",0,"hr",{}],["E5","Butiran Akaun Bank untuk Bayaran Gaji","Bank Account Details for Salary Disbursement","Untuk fail BOD/cetak","For BOD file/print","r","list",[],null,"name,ic_no,bank_name,account_number",0,"hr",{}],["E6","Kelayakan & Baki Cuti (pembukaan)","Leave Entitlement & Leave Balance (opening)","Tahunan/sakit/lain","Annual/medical/other","r","list",[],null,"name,ic_no,leave_type,entitlement_days,balance_days",0,"hr",{"view":"leave"}],["E7","Kategori Kadar Caruman (umur/kewarganegaraan)","Statutory Contribution Rate Category (age/citizenship)","Untuk kadar KWSP/PERKESO tepat","For correct EPF/SOCSO rate","r","form",[{"key":"contrib_category","bm":"Kategori kadar caruman","en":"Contribution rate category"}],null,null,0,"hr",{}],["E8","Dokumen Permohonan Kerja/Onboarding (jika guna modul)","Job Application/Onboarding Documents (if using module)","Resume, surat tawaran","Resume, offer letter","i","doc",[],null,null,0,"applicants",{}],["F1","Senarai Induk Pelanggan (Nama, Hubungan, Alamat)","Customer Master List (Name, Contact, Billing Address)","Excel/CSV","Excel/CSV","r","list",[],null,"name,contact_person,phone,email,billing_address",0,"crm",{}],["F2","Senarai Harga / Struktur Harga Produk","Price List / Product Pricing Structure","Setiap item","Per item","r","list",[],null,"sku,name,unit,price",0,"inventory",{}],["F3","Format Penomboran Invois/Sebut Harga","Invoice/Quotation Numbering Format","cth. INV-2026-001","e.g. INV-2026-001","r","form",[{"key":"numbering","bm":"Format penomboran","en":"Numbering format"}],null,null,0,"sales",{}],["F4","Terma Jualan (Terma Bayaran, Had Kredit)","Sales Terms (Payment Terms, Credit Limit)","Setiap pelanggan/lalai","Per customer/default","r","form",[{"key":"invoice_terms","bm":"Terma bayaran lalai","en":"Default payment terms","target":"invoice_terms"},{"key":"credit_note","bm":"Had kredit","en":"Credit limit"}],null,null,0,"settings",{}],["F5","Data Jualan Lepas (jika berpindah sistem, opsyenal)","Historical Sales Data (if migrating, optional)","Untuk kesinambungan laporan","For reporting continuity","i","list",[],null,"date,invoice_no,customer,amount",0,"sales",{}],["G1","Senarai Induk Produk (SKU, Nama, Unit, Kos, Harga)","Product/Item Master List (SKU, Name, Unit, Cost, Price)","Excel/CSV","Excel/CSV","r","list",[],null,"sku,name,unit,cost,price",0,"inventory",{}],["G2","Kuantiti & Nilai Stok Pembukaan (setiap item)","Opening Stock Quantity & Value (per item)","Pada tarikh potongan","As at cut-off date","r","list",[],null,"sku,quantity,unit_cost",0,"inventory",{}],["G3","Senarai Induk Pembekal (Nama, Hubungan, Terma Bayaran)","Supplier Master List (Name, Contact, Payment Terms)","Excel/CSV","Excel/CSV","r","list",[],null,"name,contact_person,phone,email,payment_terms",0,"purchasing",{"view":"suppliers"}],["G4","Bill of Materials (BOM), jika guna modul pengeluaran","Bill of Materials (BOM), if production module used","Setiap produk siap","Per finished product","i","list",[],null,"finished_sku,component_sku,quantity",0,"production",{}],["G5","Lokasi Gudang/Simpanan","Warehouse/Storage Location(s)","Untuk jejak pelbagai lokasi","For multi-location tracking","r","list",[],null,"location_name,address",0,"inventory",{}],["H1","Senarai Pengguna Sistem & Peranan Diberikan","List of System Users & Assigned Roles","Admin/SDM/Jualan/Kewangan/dll.","Admin/HR/Sales/Finance/etc.","r","list",[],null,"name,email,role",0,"settings",{}],["H2","Alamat E-mel untuk Penciptaan Akaun Pengguna","Email Addresses for User Account Creation","Satu bagi setiap pengguna","One per user","r","list",[],null,"name,email",0,"settings",{}],["H3","Kebenaran Akses Modul bagi Setiap Peranan","Module Access Permissions per Role","Konfigurasi akses modul","canAccess() config","r","form",[{"key":"access_note","bm":"Kebenaran akses bagi setiap peranan","en":"Access per role"}],null,null,0,"settings",{}],["H4","Hierarki Kelulusan (jika berkenaan \u2014 tuntutan, PO)","Approval Hierarchy (if applicable \u2014 claims, POs)","Untuk tetapan aliran kerja","For workflow setup","i","form",[{"key":"approval_note","bm":"Hierarki kelulusan","en":"Approval hierarchy"}],null,null,0,null,{}],["I1","Letterhead Rasmi / Garis Panduan Jenama","Official Letterhead / Branding Guidelines","Warna, fon, penggunaan logo","Colours, fonts, logo usage","r","doc",[],null,null,0,"settings",{}],["I2","Rujukan Susun Atur Invois/Slip Gaji/DO Pilihan","Preferred Invoice/Payslip/DO Layout Reference","Contoh atau mockup","Sample or mockup","r","doc",[],null,null,0,null,{}],["I3","Nama Penandatangan Sah & Tandatangan/Cop","Authorized Signatory Name(s) & Signature/Stamp","Untuk dokumen bercetak","For printed documents","r","doc",[{"key":"signatory","bm":"Nama penandatangan sah","en":"Authorised signatory"}],null,null,0,null,{}],["I4","Tagline Syarikat / Teks Footer Tambahan (jika ada)","Company Tagline / Additional Footer Text (if any)","Untuk templat dokumen","For document templates","i","form",[{"key":"footer_text","bm":"Tagline / teks footer","en":"Tagline / footer text"}],null,null,0,null,{}]]';
BEGIN
 SELECT id INTO vid FROM public.cob_master_versions WHERE version = 1 AND deleted_at IS NULL;
 IF vid IS NULL THEN
  INSERT INTO public.cob_master_versions (version, status, note, published_at) VALUES (1, 'published', 'M-Core onboarding checklist v1', now()) RETURNING id INTO vid;
 END IF;
 INSERT INTO public.cob_master_sections (version_id, key, name_bm, name_en, is_core, sort_order)
 SELECT vid, e->>0, e->>1, e->>2, (e->>3)::int = 1, ascii(e->>0) - 65 FROM jsonb_array_elements(secs) e
 WHERE NOT EXISTS (SELECT 1 FROM public.cob_master_sections s WHERE s.version_id = vid AND s.key = e->>0 AND s.deleted_at IS NULL);
 INSERT INTO public.cob_master_items (version_id, section_key, code, sort_order, label_bm, label_en, note_bm, note_en, requirement, item_type,
   fields, ai_action, template_header, track_expiry, urgent, module_page, module_params)
 SELECT vid, left(e->>0, 1), e->>0, substr(e->>0, 2)::int, e->>1, e->>2, e->>3, e->>4,
   CASE WHEN e->>5 = 'i' THEN 'if_applicable' ELSE 'required' END, e->>6, e->7, e->>8, e->>9, (e->>10)::int = 1,
   left(e->>0, 1) IN ('B','C','E'), e->>11, coalesce(e->12, '{}'::jsonb)
 FROM jsonb_array_elements(items) e
 WHERE NOT EXISTS (SELECT 1 FROM public.cob_master_items m WHERE m.version_id = vid AND m.code = e->>0 AND m.deleted_at IS NULL);
END
$seed$;
